      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  }
);

// Example of a POST endpoint with comprehensive validation
app.post('/users',
  authenticateToken,
  [
    body('name').trim().isLength({ min: 2, max: 50 }).escape().withMessage('Name must be 2-50 characters'),
    body('email').isEmail().normalizeEmail().withMessage('Valid email required'),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
  ],
  validateInput,
  (req, res) => {
    const { name, email, password } = req.body;

    // In production: hash password, sanitize data, and store securely
    res.status(201).json({
      message: 'User created successfully',
      user: { id: Date.now(), name, email }
    });
  }
);

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose internal error details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);

  // Security warning for development
  if (process.env.NODE_ENV !== 'production') {
    console.warn('⚠️  Running in development mode - security measures may be relaxed');
  }
});

module.exports = app;

