// Comprehensive security audit script for Express applications
const fs = require('fs');
const path = require('path');

console.log('🔒 SECURITY AUDIT REPORT\n');

// Check for common security issues
const auditResults = {
  critical: [],
  high: [],
  medium: [],
  low: [],
  passed: []
};

// 1. Check for environment files with sensitive data
const checkEnvFiles = () => {
  const envFiles = ['.env', '.env.test', '.env.local'];
  envFiles.forEach(file => {
    if (fs.existsSync(file)) {
      const content = fs.readFileSync(file, 'utf8');
      const sensitivePatterns = [
        /password=/i,
        /secret=/i,
        /key=/i,
        /token=/i,
        /aws_/i,
        /database_url/i
      ];

      const hasSensitiveData = sensitivePatterns.some(pattern => pattern.test(content));
      if (hasSensitiveData) {
        auditResults.critical.push(`CRITICAL: ${file} contains sensitive data and should not be committed to version control`);
      }
    }
  });
};

// 2. Check package.json for security dependencies
const checkDependencies = () => {
  if (fs.existsSync('package.json')) {
    const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));
    const { dependencies = {}, devDependencies = {} } = packageJson;

    const securityDeps = [
      'helmet', 'cors', 'express-rate-limit', 'express-validator',
      'bcryptjs', 'jsonwebtoken', 'dotenv'
    ];

    const missingDeps = securityDeps.filter(dep => !dependencies[dep]);
    if (missingDeps.length > 0) {
      auditResults.high.push(`HIGH: Missing security dependencies: ${missingDeps.join(', ')}`);
    } else {
      auditResults.passed.push('✅ Security dependencies are present');
    }
  }
};

// 3. Check for security headers in app code
const checkSecurityHeaders = () => {
  if (fs.existsSync('app.js')) {
    const appContent = fs.readFileSync('app.js', 'utf8');

    if (!appContent.includes('helmet')) {
      auditResults.high.push('HIGH: Missing Helmet.js for security headers');
    }

    if (!appContent.includes('cors')) {
      auditResults.medium.push('MEDIUM: Missing CORS configuration');
    }

    if (!appContent.includes('rate-limit') && !appContent.includes('rateLimit')) {
      auditResults.medium.push('MEDIUM: Missing rate limiting');
    }

    if (appContent.includes('process.env') && !appContent.includes('dotenv')) {
      auditResults.medium.push('MEDIUM: Using environment variables without dotenv');
    }
  }
};

// 4. Check for input validation
const checkInputValidation = () => {
  if (fs.existsSync('app.js')) {
    const appContent = fs.readFileSync('app.js', 'utf8');

    if (!appContent.includes('express-validator') && 
        !appContent.includes('validation') &&
        !appContent.includes('sanitize')) {
      auditResults.high.push('HIGH: Missing input validation and sanitization');
    }
  }
};

// 5. Check for authentication
const checkAuthentication = () => {
  if (fs.existsSync('app.js')) {
    const appContent = fs.readFileSync('app.js', 'utf8');

    // Simple check for auth patterns
    const authPatterns = [
      /authenticate/i,
      /auth/i,
      /jwt/i,
      /session/i,
      /passport/i
    ];

    const hasAuth = authPatterns.some(pattern => pattern.test(appContent));
    if (!hasAuth) {
      auditResults.critical.push('CRITICAL: No authentication mechanism detected');
    }
  }
};

// 6. Check for .gitignore rules
const checkGitignore = () => {
  if (fs.existsSync('.gitignore')) {
    const gitignoreContent = fs.readFileSync('.gitignore', 'utf8');

    const requiredPatterns = [
      /\.env/,
      /node_modules/,
      /\.log/,
      /dist/,
      /build/
    ];

    const missingPatterns = requiredPatterns.filter(pattern => !pattern.test(gitignoreContent));
    if (missingPatterns.length > 0) {
      auditResults.medium.push('MEDIUM: .gitignore missing important patterns');
    } else {
      auditResults.passed.push('✅ .gitignore properly configured');
    }
  } else {
    auditResults.high.push('HIGH: Missing .gitignore file');
  }
};

// Run all checks
checkEnvFiles();
checkDependencies();
checkSecurityHeaders();
checkInputValidation();
checkAuthentication();
checkGitignore();

// Generate report
console.log('📊 SECURITY FINDINGS:\n');

// Critical issues
if (auditResults.critical.length > 0) {
  console.log('🚨 CRITICAL ISSUES:');
  auditResults.critical.forEach(issue => console.log(`   • ${issue}`));
  console.log('');
}

// High issues
if (auditResults.high.length > 0) {
  console.log('🔴 HIGH PRIORITY ISSUES:');
  auditResults.high.forEach(issue => console.log(`   • ${issue}`));
  console.log('');
}

// Medium issues
if (auditResults.medium.length > 0) {
  console.log('🟡 MEDIUM PRIORITY ISSUES:');
  auditResults.medium.forEach(issue => console.log(`   • ${issue}`));
  console.log('');
}

// Low issues
if (auditResults.low.length > 0) {
  console.log('🔵 LOW PRIORITY ISSUES:');
  auditResults.low.forEach(issue => console.log(`   • ${issue}`));
  console.log('');
}

// Passed checks
if (auditResults.passed.length > 0) {
  console.log('✅ SECURITY MEASURES IN PLACE:');
  auditResults.passed.forEach(passed => console.log(`   • ${passed}`));
  console.log('');
}

// Recommendations
console.log('💡 RECOMMENDATIONS:');
console.log('   1. Immediately remove any .env files from version control');
