// Secure Secrets Management for Express Applications
// Prefer using AWS Secrets Manager, HashiCorp Vault, or similar in production

const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.encryptionKey = process.env.ENCRYPTION_KEY || this.generateEncryptionKey();
  }

  // Generate a secure encryption key (for development only)
  generateEncryptionKey() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('ENCRYPTION_KEY must be set in production environment');
    }

    const key = crypto.randomBytes(32).toString('hex');
    console.warn('⚠️  DEVELOPMENT: Auto-generated encryption key. Set ENCRYPTION_KEY in production.');
    return key;
  }

  // Encrypt a secret value
  encryptSecret(value) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    let encrypted = cipher.update(value, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag().toString('hex');

    return {
      iv: iv.toString('hex'),
      encryptedData: encrypted,
      authTag: authTag
    };
  }

  // Decrypt a secret value
  decryptSecret(encryptedObject) {
    const { iv, encryptedData, authTag } = encryptedObject;

    const decipher = crypto.createDecipheriv(
      'aes-256-gcm', 
      Buffer.from(this.encryptionKey, 'hex'), 
      Buffer.from(iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
