      apiToken: {
        value: process.env.API_TOKEN,
        required: true,
        description: 'API authentication token',
        minLength: 32
      },

      jwtSecret: {
        value: process.env.JWT_SECRET,
        required: true,
        description: 'JWT signing secret',
        minLength: 32
      },

      // AWS
