        value: process.env.AWS_ACCESS_KEY_ID,
        required: false,
        description: 'AWS access key ID',
        pattern: /^AKIA[0-9A-Z]{16}$/
      },

      awsSecretAccessKey: {
        value: process.env.AWS_SECRET_ACCESS_KEY,
        required: false,
        description: 'AWS secret access key',
        minLength: 40
      },

      // Third-party APIs
      stripeSecretKey: {
        value: process.env.STRIPE_SECRET_KEY,
        required: false,
        description: 'Stripe secret key',
        pattern: /^sk_(live|test)_[a-zA-Z0-9]{24,}$/
      },

      anthropicApiKey: {
        value: process.env.ANTHROPIC_API_KEY,
        required: false,
        description: 'Anthropic API key',
        pattern: /^sk-ant-[a-zA-Z0-9_-]{32,}$/
      }
    };

    // Validate and store secrets
    for (const [key, config] of Object.entries(secretsConfig)) {
      if (config.required && !config.value) {
        throw new Error(`Missing required secret: ${key} (${config.description})`);
      }

      if (config.value) {
        // Validate length
        if (config.minLength && config.value.length < config.minLength) {
          throw new Error(`Secret ${key} is too short. Minimum ${config.minLength} characters required.`);
        }

        // Validate pattern
        if (config.pattern && !config.pattern.test(config.value)) {
          throw new Error(`Secret ${key} has invalid format.`);
        }

        // Store the secret (encrypted in memory for additional security)
        const encrypted = this.encryptSecret(config.value);
        this.secrets.set(key, {
          encrypted,
          description: config.description,
          lastAccessed: null
        });
      }
    }

    console.log(`✅ Loaded ${this.secrets.size} secrets successfully`);
  }

  // Get a secret value (decrypted)
  getSecret(key) {
    if (!this.secrets.has(key)) {
      throw new Error(`Secret not found: ${key}`);
    }

    const secretData = this.secrets.get(key);
    secretData.lastAccessed = new Date();

    return this.decryptSecret(secretData.encrypted);
  }

  // Get secret metadata without exposing the value
  getSecretInfo(key) {
    if (!this.secrets.has(key)) {
      return null;
    }

    const { description, lastAccessed } = this.secrets.get(key);
    return {
      description,
      lastAccessed,
      isSet: true
    };
