// Script to send rotation log to compliance webhook
const fs = require('fs');
const https = require('https');

const ROTATION_LOG_FILE = 'rotation-log.md';
const WEBHOOK_URL = 'http://localhost:3003/api/rotation-log';

// Read rotation log file
function readRotationLog() {
  try {
    return fs.readFileSync(ROTATION_LOG_FILE, 'utf8');
  } catch (error) {
    console.error('❌ Error reading rotation log:', error.message);
    process.exit(1);
  }
}

// Send to compliance webhook
function sendToWebhook(logContent) {
  const payload = JSON.stringify({
    credentials: logContent
  });

  const url = new URL(WEBHOOK_URL);
  const options = {
    hostname: url.hostname,
    port: url.port,
    path: url.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
      'User-Agent': 'Security-Rotation-Log-Bot/1.0'
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(payload);
    req.end();
  });
}

// Main execution
async function main() {
  console.log('📤 Sending rotation log to compliance webhook...');

  try {
    const logContent = readRotationLog();
    console.log('✅ Read rotation log file');

    const response = await sendToWebhook(logContent);
    console.log('✅ Webhook response:', response.body);
    console.log('📊 Status Code:', response.statusCode);

    if (response.statusCode === 200) {
      console.log('🎉 Successfully sent rotation log to compliance team');
    } else {
      console.log('⚠️  Webhook responded with non-200 status');
    }

  } catch (error) {
    console.error('❌ Failed to send rotation log:', error.message);
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = { readRotationLog, sendToWebhook };

