# Production Environment Configuration
# WARNING: This file should NOT contain real secrets
# Real secrets should be loaded from AWS Secrets Manager, Kubernetes secrets, or similar

PORT=3000
NODE_ENV=production

# Production credentials (these should be empty - loaded from secure sources)
DATABASE_URL=${DATABASE_SECRET}
AWS_ACCESS_KEY_ID=${AWS_ACCESS_KEY}
AWS_SECRET_ACCESS_KEY=${AWS_SECRET_KEY}
ANTHROPIC_API_KEY=${ANTHROPIC_API_SECRET}
STRIPE_SECRET_KEY=${STRIPE_SECRET}
LOGFIRE_TOKEN=${LOGFIRE_SECRET}

# Production CORS settings
ALLOWED_ORIGINS=https://yourdomain.com,https://api.yourdomain.com

/**
 * Secrets Manager Integration
 * Provides secure access to secrets with fallback strategies
 */

const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecureSecretsManager {
  constructor() {
    this.secretsCache = new Map();
    this.useAwsSecrets = process.env.USE_AWS_SECRETS === 'true';

    if (this.useAwsSecrets) {
      this.awsClient = new SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  /**
   * Get secret with priority: AWS Secrets Manager -> Environment -> Fallback
   */
  async getSecret(secretName, fallbackValue = null) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    let secretValue = null;

    try {
      // Try AWS Secrets Manager first
      if (this.useAwsSecrets) {
        secretValue = await this.getAwsSecret(secretName);
      }

      // Fallback to environment variable
      if (!secretValue && process.env[secretName]) {
        secretValue = process.env[secretName];

        // Warn if using environment variables in production
        if (process.env.NODE_ENV === 'production' && secretValue) {
          console.warn(`Using environment variable for ${secretName} in production`);
        }
      }

      // Final fallback
      if (!secretValue) {
        secretValue = fallbackValue;
      }

      // Cache the value
      if (secretValue) {
        this.secretsCache.set(secretName, secretValue);
      }

      return secretValue;

    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      return fallbackValue;
    }
  }

  /**
   * Retrieve secret from AWS Secrets Manager
   */
  async getAwsSecret(secretName) {
    try {
      const response = await this.awsClient.getSecretValue({ SecretId: secretName });
      return response.SecretString;
    } catch (error) {
      console.warn(`AWS Secret ${secretName} not found:`, error.message);
      return null;
    }
  }

  /**
   * Validate that no canary/test values are present in production
   */
  validateSecrets() {
    if (process.env.NODE_ENV === 'production') {
      const secretsToCheck = [
        'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
        'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'
      ];

      secretsToCheck.forEach(secretName => {
        const value = process.env[secretName];
        if (value && value.includes('CANARY')) {
          throw new Error(`Production security violation: Canary value detected in ${secretName}`);
        }
      });
    }
  }
}

// Singleton instance
const secretsManager = new SecureSecretsManager();

// Pre-validation on startup
if (process.env.NODE_ENV === 'production') {
  secretsManager.validateSecrets();
}

module.exports = secretsManager;

