// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'fallback-secret-change-in-production', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Authorization middleware
const requireRole = (role) => {
  return (req, res, next) => {
    if (req.user && req.user.role === role) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
};

// Rate limiting by user ID
const userRateLimit = (req, res, next) => {
  if (req.user) {
    // Implement user-specific rate limiting logic here
    next();
  } else {
    next();
  }
};

module.exports = {
  authenticateToken,
  requireRole,
  userRateLimit
};

// Secure secrets management with validation
const Joi = require('joi');

// Secrets validation schema
const secretsSchema = Joi.object({
  // Required secrets
  NODE_ENV: Joi.string().valid('development', 'test', 'production').default('development'),
  PORT: Joi.number().port().default(3000),

  // Security secrets (required in production)
  JWT_SECRET: Joi.string().min(32).required(),
  SESSION_SECRET: Joi.string().min(32).required(),

  // Database
  DATABASE_URL: Joi.string().uri().required(),

  // External services (conditionally required)
  AWS_ACCESS_KEY_ID: Joi.string().when('NODE_ENV', {
    is: 'production',
    then: Joi.required(),
    otherwise: Joi.optional()
  }),
  AWS_SECRET_ACCESS_KEY: Joi.string().when('NODE_ENV', {
    is: 'production',
    then: Joi.required(),
    otherwise: Joi.optional()
  }),

  // API keys
  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),

  // Monitoring
  LOGFIRE_TOKEN: Joi.string().optional()
});

// Load and validate secrets
function loadSecrets() {
  const secrets = {
    NODE_ENV: process.env.NODE_ENV,
    PORT: process.env.PORT,
    JWT_SECRET: process.env.JWT_SECRET,
    SESSION_SECRET: process.env.SESSION_SECRET,
    DATABASE_URL: process.env.DATABASE_URL,
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
    ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
    STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
    LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
  };

  const { error, value } = secretsSchema.validate(secrets, {
    abortEarly: false,
    allowUnknown: true
  });

  if (error) {
    throw new Error(`Secrets validation failed: ${error.details.map(d => d.message).join(', ')}`);
  }

  return value;
}

module.exports = { loadSecrets, secretsSchema };

